import{c as s,S as a,j as i,m as t}from"./chunks/framework.VsSDrsS3.js";const g=JSON.parse('{"title":"使用 Github Pages 部署 VitePress","description":"","frontmatter":{},"headers":[],"relativePath":"blog/vitepress/deploy-vitepress-github-pages.md","filePath":"blog/vitepress/deploy-vitepress-github-pages.md","lastUpdated":1780046787000}'),r={name:"blog/vitepress/deploy-vitepress-github-pages.md"};function h(o,e,l,n,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="使用-github-pages-部署-vitepress" tabindex="-1">使用 Github Pages 部署 VitePress <a class="header-anchor" href="#使用-github-pages-部署-vitepress" aria-label="Permalink to “使用 Github Pages 部署 VitePress”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>自从用 <code>VitePress</code> 快速搭建博客系统以后，一直想部署在互联网上，然后去考察了阿里云和腾讯云，发现有点小贵。</p><p>在掘金闲逛的时候，看到这篇文章 <a href="https://juejin.cn/post/7000572105154625567#heading-1" target="_blank" rel="noreferrer">《Vuepress + GitHub Actions 实现博客自动部署！》</a>，茅塞顿开。</p><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h2><p>因为这篇 <a href="https://juejin.cn/post/7000572105154625567#heading-1" target="_blank" rel="noreferrer">博客</a> 已经写的很详细了，我就解释一下他每个步骤的作用。</p><h3 id="_1-生成-token" tabindex="-1">1. 生成 <code>Token</code> <a class="header-anchor" href="#_1-生成-token" aria-label="Permalink to “1. 生成 Token”">​</a></h3><p>获取一些权限，包括对仓库的提交，删除，监听等</p><h3 id="_2-设置-secrets" tabindex="-1">2. 设置 <code>Secrets</code> <a class="header-anchor" href="#_2-设置-secrets" aria-label="Permalink to “2. 设置 Secrets”">​</a></h3><p>用来给 <code>Action</code> 授权，来对项目做一些敏感操作。</p><h3 id="_3-编写-action" tabindex="-1">3. 编写 <code>Action</code> <a class="header-anchor" href="#_3-编写-action" aria-label="Permalink to “3. 编写 Action”">​</a></h3><p>编写 <code>yml</code> 文件，来触发 <code>Action</code> 。</p><p><a href="https://github.com/actions/checkout" target="_blank" rel="noreferrer">actions/checkout</a> <code>拉取代码</code></p><p><a href="https://github.com/JamesIves/github-pages-deploy-action" target="_blank" rel="noreferrer">JamesIves/github-pages-deploy-action</a> <code>将打包文件部署到指定分支上</code></p><p>需要注意的是这篇文章是针对 <code>VuePress</code> 来写的，所以我们需要将打包文件路径修改一下</p><div class="language-yml"><button title="Copy Code" class="copy"></button><span class="lang">yml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FOLDER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docs/.vuepress/dist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # vuepress 生成的静态文件存放的地方</span></span></code></pre></div><p>改为</p><div class="language-yml"><button title="Copy Code" class="copy"></button><span class="lang">yml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FOLDER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docs/.vitepress/dist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # vitepress 生成的静态文件存放的地方</span></span></code></pre></div><p>到这一步基本上就没啥问题了，可以在 <code>Settings</code> 里面找到自己的 <code>Pages</code> 地址</p><blockquote><p>项目地址 -&gt; Settings -&gt; Pages -&gt; Visit site</p></blockquote><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>VitePress + GitHub Pages 是个人博客的轻量级方案，关键在于区分源码仓库和 Pages 部署仓库，通过 GitHub Actions 实现推送自动构建即可。</p>',22)])])}const k=s(r,[["render",h]]);export{g as __pageData,k as default};
